import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32
#define THREADS_X 8
#define THREADS_Y 32
#define WPT (TILE_DIM / THREADS_X) // Work per thread

__global__ void matmul_kernel_unroll(const float* A, const float* B, float* C, int N) {
    __shared__ float tile_A[TILE_DIM][TILE_DIM];
    __shared__ float tile_B[TILE_DIM][TILE_DIM];

    int row = blockIdx.y * TILE_DIM + threadIdx.y;
    int col = blockIdx.x * TILE_DIM + threadIdx.x;

    int a_col, b_row;

    float sum[WPT];
    for(int i=0; i<WPT; ++i) sum[i] = 0.0f;

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tile of A
        a_col = t * TILE_DIM + threadIdx.x;
        if (row < N && a_col < N) {
            for(int i=0; i<WPT; ++i)
                tile_A[threadIdx.y][threadIdx.x + i*THREADS_X] = A[row * N + a_col + i*THREADS_X];
        } else {
            for(int i=0; i<WPT; ++i)
                tile_A[threadIdx.y][threadIdx.x + i*THREADS_X] = 0.0f;
        }

        // Load tile of B
        b_row = t * TILE_DIM + threadIdx.y;
        if (b_row < N && col < N) {
            for(int i=0; i<WPT; ++i)
                tile_B[threadIdx.y][threadIdx.x + i*THREADS_X] = B[b_row * N + col + i*THREADS_X];
        } else {
            for(int i=0; i<WPT; ++i)
                tile_B[threadIdx.y][threadIdx.x + i*THREADS_X] = 0.0f;
        }
        __syncthreads();

        for (int k = 0; k < TILE_DIM; ++k) {
            #pragma unroll
            for(int i=0; i<WPT; ++i)
                sum[i] += tile_A[threadIdx.y][k] * tile_B[k][threadIdx.x + i*THREADS_X];
        }
        __syncthreads();
    }

    if (row < N && col < N) {
        for(int i=0; i<WPT; ++i)
            C[row * N + col + i*THREADS_X] = sum[i];
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions are not compatible for multiplication");

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const dim3 threads(THREADS_X, THREADS_Y);
    const dim3 blocks((N + TILE_DIM - 1) / TILE_DIM, (N + TILE_DIM - 1) / TILE_DIM);

    matmul_kernel_unroll<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );
    return C;
}
"""

